    39	export interface PropertyRepository {
    40	  /** Properties by creation time, ties broken by id in the same direction (S2.3). */
    41	  list(options: ListOptions): Promise<PropertyRecord[]>;
    42	  /** `id` must already be a well-formed UUID (Postgres rejects anything else). */
    43	  findById(id: string): Promise<PropertyRecord | null>;
    44	  findByAddress(address: Address): Promise<PropertyRecord | null>;
    45	  /** Inserts, or reports the existing row when the address unique key is already taken. */
    46	  insert(data: NewProperty): Promise<InsertResult>;
    47	  /** Returns whether a row was removed; `id` must already be a well-formed UUID. */
    48	  deleteById(id: string): Promise<boolean>;
    49	}
    50	
    51	const UNIQUE_VIOLATION = 'P2002';
    52	
    53	/**
    54	 * Prisma's `contains` passes the value into ILIKE unescaped, so `%` and `_` would act as
    55	 * wildcards. Escape them (and the escape character itself) to match literally (S3.3).
    56	 */
    57	const escapeLike = (value: string) => value.replace(/[\\%_]/g, (char) => `\\${char}`);
    58	
    59	export function createPropertyRepository(prisma: PrismaClient): PropertyRepository {
    60	  const findByAddress = ({ street, city, state, zipCode }: Address) =>
    61	    prisma.property.findUnique({
    62	      where: { street_city_state_zipCode: { street, city, state, zipCode } },
    63	    });
    64	
    65	  return {
    66	    list: ({ direction, filter = {} }) =>
    67	      prisma.property.findMany({
    68	        where: {
    69	          // S3.2 case-insensitive substring.
    70	          ...(filter.city && { city: { contains: escapeLike(filter.city), mode: 'insensitive' } }),
    71	          ...(filter.zipCode && { zipCode: filter.zipCode }),
    72	          ...(filter.state && { state: filter.state }),
    73	        },
    74	        orderBy: [{ createdAt: direction }, { id: direction }],
    75	      }),
    76	
    77	    findById: (id) => prisma.property.findUnique({ where: { id } }),
    78	
    79	    findByAddress,
    80	
    81	    async insert({ weatherData, ...fields }) {
    82	      try {
    83	        const property = await prisma.property.create({
    84	          data: { ...fields, weatherData: weatherData as Prisma.InputJsonObject },
    85	        });
    86	        return { ok: true, property };
    87	      } catch (error) {
    88	        if (
    89	          error instanceof Prisma.PrismaClientKnownRequestError &&
    90	          error.code === UNIQUE_VIOLATION
    91	        ) {
    92	          // Lost a race with a concurrent create of the same address (S5.4).
    93	          const existing = await findByAddress(fields);
    94	          if (existing) return { ok: false, duplicateOf: existing.id };
    95	        }
    96	        throw error;
    97	      }
    98	    },
    99	
   100	    // deleteMany reports a count instead of throwing when the row is already gone (S6.3).
   101	    deleteById: async (id) => (await prisma.property.deleteMany({ where: { id } })).count > 0,
   102	  };
