     8	import type { WeatherFailureReason, WeatherstackClient } from '../weatherstack/client.ts';
     9	
    10	export interface CreatePropertyInput {
    11	  street: string;
    12	  city: string;
    13	  state: USState;
    14	  zipCode: string;
    15	}
    16	
    17	export interface FieldError {
    18	  field: keyof CreatePropertyInput;
    19	  message: string;
    20	}
    21	
    22	export type CreatePropertyResult =
    23	  | { kind: 'created'; property: PropertyRecord }
    24	  | { kind: 'invalidInput'; fieldErrors: FieldError[] }
    25	  | { kind: 'duplicate'; existingPropertyId: string }
    26	  | { kind: 'weatherUnavailable'; reason: WeatherFailureReason };
    27	
    28	export type CreateProperty = (input: CreatePropertyInput) => Promise<CreatePropertyResult>;
    29	
    30	/** S5.6 — Weatherstack names territories only in `region`, so one list covers every USState. */
    31	const US_COUNTRIES: ReadonlySet<string> = new Set([
    32	  'USA United States of America',
    33	  'United States of America',
    34	]);
    35	
    36	/** S5.3 — rules GraphQL can't express. `state` is already a valid enum value. */
    37	const Input = z.object({
    38	  street: z
    39	    .string()
    40	    .trim()
    41	    .min(1, 'Street is required.')
    42	    .max(200, 'Street must be at most 200 characters.'),
    43	  city: z
    44	    .string()
    45	    .trim()
    46	    .min(1, 'City is required.')
    47	    .max(100, 'City must be at most 100 characters.'),
    48	  zipCode: z.string().regex(/^\d{5}$/, 'Zip code must be exactly 5 digits.'),
    49	});
    50	
    51	export interface CreatePropertyDeps {
    52	  properties: Pick<PropertyRepository, 'findByAddress' | 'insert'>;
    53	  weatherstack: WeatherstackClient;
    54	  logger?: Pick<Console, 'warn'>;
    55	}
    56	
    57	/**
    58	 * S5 — validate → duplicate check → one Weatherstack call → persist. Anything short of complete
    59	 * weather data aborts before writing (ADR-0004).
    60	 */
    61	export function createPropertyService({
    62	  properties,
    63	  weatherstack,
    64	  logger = console,
    65	}: CreatePropertyDeps): CreateProperty {
    66	  return async (input) => {
    67	    const parsed = Input.safeParse(input);
    68	    if (!parsed.success) {
    69	      return {
    70	        kind: 'invalidInput',
    71	        fieldErrors: parsed.error.issues.map((issue) => ({
    72	          field: issue.path[0] as FieldError['field'],
    73	          message: issue.message,
    74	        })),
    75	      };
    76	    }
    77	
    78	    const address: Address = { ...parsed.data, state: input.state };
    79	    const existing = await properties.findByAddress(address);
    80	    if (existing) return { kind: 'duplicate', existingPropertyId: existing.id };
    81	
    82	    const lookup = await weatherstack.current(`${address.zipCode}, ${address.state}, USA`);
    83	    if (!lookup.ok) {
    84	      logger.warn(`Weatherstack lookup failed: ${lookup.reason} (${lookup.detail})`);
    85	      return { kind: 'weatherUnavailable', reason: lookup.reason };
    86	    }
    87	
    88	    const { location, current } = lookup.response;
    89	    if (!US_COUNTRIES.has(location.country)) {
    90	      logger.warn(`Weatherstack resolved ${address.zipCode} outside the USA: ${location.country}`);
    91	      return { kind: 'weatherUnavailable', reason: 'LOCATION_MISMATCH' };
    92	    }
    93	
    94	    const inserted = await properties.insert({
    95	      ...address,
    96	      weatherData: current,
    97	      lat: location.lat,
    98	      long: location.lon,
    99	    });
   100	    return inserted.ok
   101	      ? { kind: 'created', property: inserted.property }
   102	      : { kind: 'duplicate', existingPropertyId: inserted.duplicateOf };
   103	  };
   104	}
