    15	
    16	export const NO_FILTER: FilterValues = { city: '', zipCode: '', state: '' };
    17	
    18	/** Blank fields mean "any" (S3.4); the server trims and validates again. */
    19	export function toPropertyFilter({ city, zipCode, state }: FilterValues): PropertyFilter {
    20	  return {
    21	    city: city.trim() || null,
    22	    zipCode: zipCode.trim() || null,
    23	    state: (state as USState) || null,
    24	  };
    25	}
    26	
    27	const sameFilter = (a: FilterValues, b: FilterValues) =>
    28	  a.city === b.city && a.zipCode === b.zipCode && a.state === b.state;
    29	
    30	export const isFiltering = (values: FilterValues) =>
    31	  Object.values(toPropertyFilter(values)).some((value) => value !== null);
    32	
    33	/** S3 — filters apply on submit, so a half-typed zip never reaches the API. */
    34	export function PropertyFilters({
    35	  applied,
